/**
 * A cyclic {@code COUNT} join — a triangle — is the worst-case-optimal join's fast path: leapfrog stays bounded well
 * below the product of its inputs, which is the whole reason the strategy exists. The IR/Janino aggregate kernel has no
 * such bound; it enumerates what the interpreter would and hash-dedups, just more cheaply per row. When both are viable
 * the kernel must yield.
 * <p>
 * This is the HIGHLY_CONNECTED q8 regression in miniature. That query went from 110.68ms to 241.06ms the day the kernel
 * learned to compile a {@code JoinPlan}: the decline {@code irKernel:agg:unsupported:JoinPlan} disappeared, the kernel
 * became admissible, and it captured the row from WCOJ purely because its rung sits higher in the dispatch ladder.
 * <p>
 * The companion case {@link #nonCyclicShapeRemainsSemanticNative()} stops the fix from becoming a different bug: the
 * non-cyclic shape must remain on a semantic native route with no generic host or island. Direct kernel reachability
 * and WCOJ refusal for acyclic plans are pinned by {@link LmdbNativeKernelLoweringTest}.
 */
public class LmdbNativeKernelWcojGuardTest {

	private static final String EX = "http://example.com/";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		// Both strategies must be live, so that the kernel would be attempted absent the specialization order.
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "true");
		System.setProperty("rdf4j.lmdb.factorizedTail.enabled", "false");
		System.setProperty("rdf4j.lmdb.parallel.enabled", "false");
		LmdbNativeKernelExecution.resetMetrics();
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI edge = vf.createIRI(EX, "connectsTo");
			// Several overlapping triangles, plus chain edges that are not part of any cycle.
			for (int t = 0; t < 8; t++) {
				IRI a = vf.createIRI(EX, "n" + (3 * t));
				IRI b = vf.createIRI(EX, "n" + (3 * t + 1));
				IRI c = vf.createIRI(EX, "n" + (3 * t + 2));
				connection.add(a, edge, b);
				connection.add(b, edge, c);
				connection.add(c, edge, a);
			}
			for (int i = 0; i < 8; i++) {
				connection.add(vf.createIRI(EX, "tail" + i), edge, vf.createIRI(EX, "tail" + (i + 1)));
			}
		}
	}

	@AfterEach
	public void tearDown() {
		System.clearProperty("rdf4j.lmdb.janinoCodegen.enabled");
		System.clearProperty("rdf4j.lmdb.factorizedTail.enabled");
		System.clearProperty("rdf4j.lmdb.parallel.enabled");
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Test
	public void cyclicCountDoesNotAttemptIrAggregate() {
		String query = "PREFIX ex: <" + EX + "> "
				+ "SELECT (COUNT(*) AS ?c) WHERE { ?a ex:connectsTo ?b . ?b ex:connectsTo ?d . ?d ex:connectsTo ?a }";

		// Sanity: this shape really is the worst-case-optimal join's fast path (guards the fixture, not the fix).
		assertThat(executionPath(query)).isEqualTo(LmdbNativeAttemptMetrics.PATH_WCOJ);

		// Isolate the kernel-attempt counter to a single clean execution (the explain above also executes).
		LmdbNativeKernelExecution.resetMetrics();

		long count;
		try (SailRepositoryConnection connection = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(connection.prepareTupleQuery(query).evaluate());
			assertThat(rows).hasSize(1);
			count = ((Literal) rows.get(0).getValue("c")).longValue();
		}
		assertThat(count).as("each of the 8 triangles is matched once per starting vertex").isEqualTo(24L);

		assertThat(LmdbNativeKernelExecution.AGG_PLANNED.get())
				.as("the IR aggregate kernel must not intercept a row a worst-case-optimal join would have served")
				.isZero();
	}

	@Test
	public void nonCyclicShapeRemainsSemanticNative() {
		// An acyclic chain: findCyclicCore refuses it, so it must not be routed through WCOJ or a generic evaluator.
		String query = "PREFIX ex: <" + EX + "> "
				+ "SELECT (COUNT(*) AS ?c) WHERE { ?a ex:connectsTo ?b . ?b ex:connectsTo ?d }";

		assertThat(executionPath(query))
				.as("an acyclic aggregate is not the WCOJ engine's shape")
				.isNotEqualTo(LmdbNativeAttemptMetrics.PATH_WCOJ);

		long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		long islandsBefore = LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(connection.prepareTupleQuery(query).evaluate());
			assertThat(rows).hasSize(1);
			assertThat(((Literal) rows.get(0).getValue("c")).longValue()).isEqualTo(31L);
		}
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get()).isEqualTo(hostedBefore);
		assertThat(LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get()).isEqualTo(islandsBefore);
	}

	private String executionPath(String query) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			String path = findStrategy(connection.prepareTupleQuery(query)
					.explain(Explanation.Level.Telemetry)
					.toGenericPlanNode());
			assertThat(path).as("expected a nativeExecutionPath metric in the explanation").isNotNull();
			return path;
		}
	}

	private static String findStrategy(GenericPlanNode node) {
		if (node == null) {
			return null;
		}
		String value = node.getStringMetricActual("nativeExecutionPath");
		if (value != null) {
			return value;
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				String found = findStrategy(child);
				if (found != null) {
					return found;
				}
			}
		}
		return null;
	}
}
